VRT_L("tle-c-svt-r29",R({"duree":20,"titre":"Régulation des hormones sexuelles chez la femme","accroche":"Un frein, puis un accélérateur.","intro":"Selon la phase du cycle, le rétrocontrôle change de sens.","objectifs":["décrire les rétrocontrôles","expliquer le pic de LH","exploiter un document"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Le <strong>cycle sexuel</strong> dure environ 28 jours. Il couple un cycle ovarien et un cycle utérin.</div>"},{"t":"Rôles","verrou":true,"illus":{"legende":"Le cycle sexuel de la femme : ovaire, hormones, utérus.","ref":"fab263da78a"}},{"t":"Les rétrocontrôles","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"svt","rang":29,"apc":{"module":"Santé reproductive et nutritionnelle","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre certaines maladies métaboliques","situation":"Une enseignante de Yaoundé présente une courbe des hormones du cycle à sa classe.","tache":"Dis pourquoi la LH présente un pic."},"verrou":true,"nq":10,"labo":true}));
VRT_L("tle-c-svt-r30",R({"duree":20,"titre":"Stérilité et infertilité","accroche":"Une difficulté qui touche les deux sexes.","intro":"L'infertilité d'un couple peut avoir des causes masculines, féminines ou mixtes.","objectifs":["citer des causes","citer des examens","refuser la stigmatisation"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>L'<strong>infertilité</strong> est l'absence de grossesse après au moins un an de rapports réguliers non protégés.</div>"},{"t":"Causes","verrou":true},{"t":"Solutions","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"svt","rang":30,"apc":{"module":"Santé reproductive et nutritionnelle","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre certaines maladies métaboliques","situation":"Une femme à Bafoussam est accusée seule de ne pas avoir d'enfant.","tache":"Rédige un message pour la famille."},"verrou":true,"nq":10,"labo":true}));
VRT_L("tle-c-svt-r31",R({"duree":20,"titre":"Glycémie : variations et régulation hormonale","accroche":"Insuline et glucagon, deux hormones antagonistes.","intro":"Le pancréas ajuste la glycémie grâce à deux hormones.","objectifs":["préciser les rôles","interpréter l'expérience du foie lavé","expliquer la régulation"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>glycémie</strong> est la concentration de glucose dans le sang. À jeun, elle est voisine de 1 g/L.</div>"},{"t":"Les deux hormones","verrou":true,"illus":{"legende":"La régulation de la glycémie par l'insuline et le glucagon.","ref":"f262c2a1321"}},{"t":"Le foie lavé","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"svt","rang":31,"apc":{"module":"Santé reproductive et nutritionnelle","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre certaines maladies métaboliques","situation":"En TP à Mbouda, on rince un foie frais jusqu'à ce que l'eau ne contienne plus de glucose (test négatif à la liqueur de Fehling) ; après 30 minutes à 37 °C, l'eau de rinçage redonne un test positif. Un foie bouilli ne redonne pas de glucose.","tache":"Interprète ces résultats."},"verrou":true,"nq":10,"labo":true}));
VRT_L("tle-c-svt-r32",R({"duree":20,"titre":"Diabète et hypoglycémie","accroche":"Une élévation permanente abîme les organes.","intro":"Le diabète résulte d'une régulation défaillante de la glycémie.","objectifs":["distinguer type 1 et type 2","citer les complications","prévenir"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Le <strong>diabète</strong> se caractérise par une glycémie à jeun égale ou supérieure à 1,26 g/L, vérifiée à deux reprises.</div>"},{"t":"Les types","verrou":true},{"t":"Complications et prévention","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"svt","rang":32,"apc":{"module":"Santé reproductive et nutritionnelle","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre certaines maladies métaboliques","situation":"Dans un quartier de Bafoussam, sur 300 adultes dépistés, 36 ont une glycémie à jeun supérieure à 1,26 g/L et 60 une tension supérieure à 14/9 ; la plupart mangent beaucoup de friture et marchent peu.","tache":"Calcule les pourcentages et rédige des conseils argumentés pour le quartier."},"verrou":true,"nq":10,"labo":true}));
VRT_L("tle-c-svt-r33",R({"duree":20,"titre":"Pression artérielle : mesure et facteurs","accroche":"Deux nombres essentiels.","intro":"La pression artérielle est la force exercée par le sang sur la paroi des artères.","objectifs":["définir systolique et diastolique","mesurer","citer les facteurs"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>pression artérielle</strong> s'exprime par deux valeurs : la pression systolique et la pression diastolique.</div>"},{"t":"Mesure","verrou":true,"illus":{"legende":"La régulation nerveuse de la pression artérielle.","ref":"f1efb3746e5"}},{"t":"Facteurs","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"svt","rang":33,"apc":{"module":"Santé reproductive et nutritionnelle","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre certaines maladies métaboliques","situation":"Une infirmière de Foumban mesure 16/10 chez un commerçant au repos.","tache":"Interprète et conseille."},"verrou":true,"nq":10,"labo":true}));
VRT_L("tle-c-svt-r34",R({"duree":20,"titre":"Élévation et baisse permanentes de la tension","accroche":"L'hypertension est longtemps silencieuse.","intro":"Une tension anormale durable abîme les organes.","objectifs":["citer les conséquences","citer les facteurs de risque","prévenir"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>L'<strong>hypertension artérielle</strong> est une élévation persistante de la pression artérielle.</div>"},{"t":"Conséquences","verrou":true},{"t":"Prévention","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"svt","rang":34,"apc":{"module":"Santé reproductive et nutritionnelle","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre certaines maladies métaboliques","situation":"Un retraité de Douala arrête son traitement dès qu'il se sent bien.","tache":"Explique-lui le risque."},"verrou":true,"nq":10,"labo":true}));
VRT_L("tle-c-svt-r35",R({"duree":20,"titre":"Intégration : diabète et hypertension","accroche":"Deux maladies liées au mode de vie.","intro":"Cette séance mobilise les notions du chapitre pour résoudre une situation réelle, comme à la partie B de l'épreuve.","objectifs":["identifier le problème","mobiliser les ressources","rédiger une réponse argumentée"],"parties":[{"t":"La notion à mobiliser","html":"<div class='def'><b>Définition</b>Le <strong>diabète de type 2</strong> et l'<strong>hypertension</strong> sont favorisés par une alimentation déséquilibrée et la sédentarité.</div>"},{"t":"Le plan de la réponse","verrou":true,"illus":{"legende":"La régulation de la glycémie.","ref":"f262c2a1321"}},{"t":"La production attendue","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"svt","rang":35,"apc":{"module":"Santé reproductive et nutritionnelle","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre certaines maladies métaboliques","situation":"Une enquête à Bafoussam montre une hausse du diabète et de l'hypertension chez les commerçants.","tache":"Élabore une affiche de prévention."},"verrou":true,"nq":10,"labo":true}));
VRT_L("tle-c-svt-r36",R({"duree":20,"titre":"Catastrophes naturelles et gestion","accroche":"Prévoir, prévenir, protéger.","intro":"Le Cameroun connaît volcanisme, glissements de terrain et inondations.","objectifs":["définir aléa et catastrophe","distinguer prévision et prévention","donner des exemples camerounais"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définition</b>Un <strong>aléa</strong> est un phénomène naturel possible. Une <strong>catastrophe</strong> est un événement qui cause de graves dommages à une société.</div>","illus":{"legende":"La Ligne du Cameroun : volcans et lacs de cratère.","ref":"f179b3e3c8c"}},{"t":"Exemples","html":"<ul><li>Éruptions du mont Cameroun.</li><li>Dégazage du lac Nyos en 1986.</li><li>Glissements de terrain, comme à Gouache en 2019 à Bafoussam.</li></ul>","labo":{"type":"pente"},"illus":{"legende":"Le volcan, éruptions effusives et explosives.","ref":"fc4ea4f73fb"}},{"t":"Gestion","html":"<p>La <strong>prévision</strong> estime la survenue ; la <strong>prévention</strong> réduit la vulnérabilité par l'occupation réfléchie des sols et l'information.</p>","retenir":"Prévention : réduire la vulnérabilité."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Évaluation des savoirs (QCM).</strong> Les catastrophes naturelles d'origine interne comprennent :</p><ol type='a'><li>les inondations et les glissements de terrain</li><li>les sécheresses et la désertification</li><li>les cyclones et les tempêtes</li><li>les séismes et les éruptions volcaniques</li></ol><details><summary>Voir la réponse</summary><p><strong>les séismes et les éruptions volcaniques</strong>. Elles sont liées à l'énergie interne de la Terre.</p></details><p><strong>Évaluation des savoir-faire.</strong></p><p>Cite une catastrophe survenue au Cameroun.</p><details><summary>Voir la réponse</summary><p>(Exemple : le lac Nyos en 1986.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Compétence visée.</strong> Prévenir les catastrophes et valoriser les ressources de son environnement.</p><p><strong>Situation.</strong> Après de fortes pluies, des familles construisent au pied d'une colline déboisée ; la commune envisage une évacuation. Un journal parle aussi des inondations dans les bas-fonds.</p><p><strong>Consigne 1.</strong> Distingue aléa, vulnérabilité et risque à partir de cet exemple.</p><p><strong>Consigne 2.</strong> Dans un texte d'une dizaine de lignes, propose à la commune un plan de gestion avant, pendant et après la catastrophe.</p><details><summary>Voir une réponse attendue</summary><p>Aléa : le glissement ou l'inondation possible ; vulnérabilité : les maisons et personnes exposées ; risque : leur combinaison. Avant : cartographier les zones à risque, interdire les constructions, reboiser, drainer, informer. Pendant : alerte, évacuation, secours. Après : prise en charge des sinistrés, évaluation des dégâts, reconstruction hors zone à risque.</p></details></div>","retenir":"Savoir-être mobilisé : Sens de la responsabilité."}],"revision":["Aléa.","Catastrophe.","Prévision et prévention."],"exo":"<p>Cite une catastrophe survenue au Cameroun. <em>(Exemple : le lac Nyos en 1986.)</em></p>","quiz":[{"q":"Les catastrophes naturelles d'origine interne comprennent :","r":["les inondations et les glissements de terrain","les sécheresses et la désertification","les cyclones et les tempêtes","les séismes et les éruptions volcaniques"],"b":3,"e":"Elles sont liées à l'énergie interne de la Terre."},{"q":"La catastrophe du lac Nyos (1986) a été provoquée par :","r":["un dégagement massif de CO₂","une coulée de lave venue du fond","un tsunami provoqué par un glissement","un séisme seul de forte magnitude"],"b":0,"e":"Le gaz a asphyxié les habitants des vallées."},{"q":"Le dégazage du lac Nyos consiste à :","r":["vider entièrement le lac par un canal","évacuer progressivement le CO₂ dissous par des colonnes","chauffer l'eau du fond pour chasser le gaz","remplir le lac avec de l'eau de rivière froide pour diluer le gaz"],"b":1,"e":"On empêche une nouvelle accumulation."},{"q":"La dernière éruption du mont Cameroun date de :","r":["1800","1950","2000","2025"],"b":2,"e":"Les coulées ont menacé la route de Limbé."},{"q":"La gestion d'un risque comprend :","r":["l'attente que l'événement se produise pour réagir ensuite","la construction d'habitations dans les zones les plus exposées pour les surveiller","la reconstruction seule, sans aucune mesure avant l'événement","la prévision, la prévention, l'alerte et l'organisation des secours"],"b":3,"e":"Elle réduit la vulnérabilité des populations."},{"q":"Un plan d'évacuation doit indiquer :","r":["les itinéraires et les lieux de regroupement","les noms des élèves absents et des classes","les horaires de la cantine et de la récréation","les règlements intérieurs de chaque salle"],"b":0,"e":"Chacun doit savoir où aller."},{"q":"Pendant un séisme à l'intérieur, il faut :","r":["courir dans les escaliers pour sortir au plus vite","s'abriter sous un meuble solide, loin des vitres","prendre l'ascenseur pour descendre rapidement","se placer près des fenêtres pour voir dehors"],"b":1,"e":"On se protège des chutes d'objets."},{"q":"Les constructions parasismiques :","r":["s'effondrent plus vite lors des secousses","sont interdites dans les zones à risque","résistent mieux aux secousses","coûtent moins cher et sont moins solides"],"b":2,"e":"Elles respectent des normes de chaînage."},{"q":"Le risque est le produit :","r":["du hasard seul, sans autre facteur","de la météo et des saisons de l'année","de la population seule, sans l'aléa","de l'aléa et de la vulnérabilité"],"b":3,"e":"Une zone dangereuse inhabitée a un risque faible."},{"q":"La surveillance d'un volcan utilise :","r":["des sismographes, des mesures de gaz et de déformation du sol","un thermomètre de cuisine plongé dans la lave du cratère pendant la nuit","un glucomètre et un tensiomètre","des jumelles seulement, sans autre appareil"],"b":0,"e":"Elle permet de lancer l'alerte à temps."}],"c":"Tle C","m":"svt","rang":36,"apc":{"module":"Catastrophes et valorisation","famille":"Préservation de l'environnement","agir":"Prévenir les catastrophes et valoriser les ressources de son environnement","situation":"Des familles de Bafoussam construisent au pied d'une colline qui s'effondre à chaque pluie abondante.","tache":"Propose une conduite."},"gratuit":true}));
VRT_L("tle-c-svt-r37",R({"duree":20,"titre":"Intégration : vivre près d'un volcan","accroche":"Limbé, Buea et le mont Cameroun.","intro":"Cette séance mobilise les notions du chapitre pour résoudre une situation réelle, comme à la partie B de l'épreuve.","objectifs":["identifier le problème","mobiliser les ressources","rédiger une réponse argumentée"],"parties":[{"t":"La notion à mobiliser","html":"<div class='def'><b>Définition</b>La <strong>prévention</strong> combine connaissance scientifique et actions collectives.</div>"},{"t":"Le plan de la réponse","verrou":true,"illus":{"legende":"Le volcan.","ref":"fc4ea4f73fb"}},{"t":"La production attendue","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"svt","rang":37,"apc":{"module":"Catastrophes et valorisation","famille":"Préservation de l'environnement","agir":"Prévenir les catastrophes et valoriser les ressources de son environnement","situation":"Des habitants de Buea ignorent les consignes en cas d'éruption du mont Cameroun.","tache":"Rédige un message d'information."},"verrou":true,"nq":10,"labo":true}));
