VRT_L("tle-c-svt-r41",R({"duree":20,"titre":"Les biocarburants","accroche":"Une énergie à partir de la biomasse.","intro":"Les biocarburants proviennent de matières organiques renouvelables.","objectifs":["définir les biocarburants","décrire la production","discuter les limites"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Un <strong>biocarburant</strong> est un carburant issu de la biomasse. Le bioéthanol vient de la fermentation de sucres ; le biodiesel vient d'huiles végétales.</div>"},{"t":"La production","verrou":true,"illus":{"legende":"Des déchets aux biocarburants.","ref":"fcfe7126fb1"}},{"t":"Limites","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"svt","rang":41,"apc":{"module":"Catastrophes et valorisation","famille":"Préservation de l'environnement","agir":"Prévenir les catastrophes et valoriser les ressources de son environnement","situation":"Une unité agricole de Mbalmayo veut valoriser des résidus de canne à sucre.","tache":"Propose un produit et son principe."},"verrou":true,"nq":10,"labo":true}));
